-- Generated by scripts/build_compiled.py from src/fraudrules/rules/synthetic-identity/si-004-device-across-identities.yaml. Do not edit.
-- SI-004 One device submitting applications for several identities
SELECT 'SI-004' AS rule_id, 'applications' AS anchor_table, a.id AS anchor_id
FROM applications AS a
JOIN applications AS b ON b.device_id = a.device_id AND b.ts <= a.ts AND b.ts > a.ts - 2592000
WHERE 1 = 1 AND 1 = 1
GROUP BY a.id
HAVING COUNT(DISTINCT b.ssn_token) >= 3;
